fn append_vectors<T: Copy>(v1: &Vec<T>, v2: &Vec<T>) -> Vec<T> {
    // create a new vector with capacity to hold both v1 and v2 elements
    let mut result = Vec::with_capacity(v1.len() + v2.len());
    // extend with elements from v1
    for &item in v1.iter() {
        result.push(item);
    }
    // extend with elements from v2
    for &item in v2.iter() {
        result.push(item);
    }
    result
}

fn replace_last_element(first: &Vec<i32>, second: &Vec<i32>) -> Vec<i32> {
    // first must be non-empty as per specification
    let n = first.len();
    // construct result vector
    let mut result = Vec::with_capacity((n - 1) + second.len());
    // copy all elements from first except the last one
    for i in 0..(n - 1) {
        result.push(first[i]);
    }
    // append all elements from second
    for &item in second.iter() {
        result.push(item);
    }
    result
}